int stringToInteger(const std::string& s) {
    int result = 0;
    int sign = 1;
    size_t i = 0;

    // 处理空白字符
    while (i < s.length() && s[i] == ' ') ++i;

    // 处理正负号
    if (i < s.length() && (s[i] == '+' || s[i] == '-')) {
        sign = (s[i] == '+') ? 1 : -1;
        ++i;
    }

    // 处理数字
    while (i < s.length() && std::isdigit(s[i])) {
        result = result * 10 + (s[i] - '0');
        ++i;
    }

    return sign * result;
}

