std::vector<uint8_t> modbus_crc16_le(const std::vector<uint8_t>& data) {
    uint16_t crc = 0xFFFFu;
    for (uint8_t b : data) {
        crc ^= b;
        for (int i = 0; i < 8; ++i) {
            if (crc & 1u) crc = (crc >> 1) ^ 0xA001u;
            else crc >>= 1;
        }
    }
    return { static_cast<uint8_t>(crc & 0xFFu), static_cast<uint8_t>(crc >> 8) };
}

