void merge(std::vector<int> &a, int l, int m, int r) {
    std::vector<int> tmp(a.begin() + l, a.begin() + r + 1);
    int i = 0, j = m - l + 1, k = l, sz = r - l + 1;
    while (i <= m - l && j < sz)
        a[k++] = (tmp[i] <= tmp[j]) ? tmp[i++] : tmp[j++];
    while (i <= m - l) a[k++] = tmp[i++];
    while (j < sz) a[k++] = tmp[j++];
}

void merge_sort(std::vector<int> &a, int l, int r) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    merge_sort(a, l, m);
    merge_sort(a, m + 1, r);
    merge(a, l, m, r);
}

