int partition(std::vector<int> &a, int lo, int hi) {
    int mid = lo + (hi - lo) / 2;
    if (a[lo] > a[mid]) std::swap(a[lo], a[mid]);
    if (a[lo] > a[hi]) std::swap(a[lo], a[hi]);
    if (a[mid] > a[hi]) std::swap(a[mid], a[hi]);
    std::swap(a[mid], a[hi - 1]);
    int pivot = a[hi - 1], i = lo, j = hi - 1;
    while (true) { while (a[++i] < pivot); while (a[--j] > pivot); if (i >= j) break; std::swap(a[i], a[j]); }
    std::swap(a[i], a[hi - 1]);
    return i;
}

void quick_sort(std::vector<int> &a, int lo, int hi) {
    if (lo + 8 <= hi) {
        int p = partition(a, lo, hi);
        quick_sort(a, lo, p - 1);
        quick_sort(a, p + 1, hi);
    } else { std::sort(a.begin() + lo, a.begin() + hi + 1); }
}

