int quickselect(std::vector<int> arr, int k) {
    int lo = 0, hi = (int)arr.size() - 1;
    while (lo < hi) {
        int pivot = arr[lo + (hi - lo) / 2];
        int i = lo - 1, j = hi + 1;
        while (true) { while (arr[++i] < pivot); while (arr[--j] > pivot); if (i >= j) break; std::swap(arr[i], arr[j]); }
        if (j < k) lo = j + 1; else hi = j;
    }
    return arr[k];
}

