const int INF = std::numeric_limits<int>::max() / 2;

std::pair<std::vector<int>, bool> bellman_ford(int n, const std::vector<std::tuple<int,int,int>> &edges, int src) {
    std::vector<int> dist(n, INF);
    dist[src] = 0;
    for (int i = 0; i < n - 1; i++)
        for (auto &[u, v, w] : edges)
            if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
    bool neg_cycle = false;
    for (auto &[u, v, w] : edges)
        if (dist[u] + w < dist[v]) { neg_cycle = true; break; }
    return {dist, neg_cycle};
}

#include <string>
#include <vector>

std::vector<int> rabin_karp(const std::string &text, const std::string &pat) {
    const int BASE = 256, MOD = 1e9 + 7;
    int n = text.size(), m = pat.size();
    if (m > n) return {};
    long long p_hash = 0, t_hash = 0, power = 1;
    std::vector<int> result;
    for (int i = 0; i < m; i++) {
        p_hash = (p_hash * BASE + pat[i]) % MOD;
        t_hash = (t_hash * BASE + text[i]) % MOD;
        if (i > 0) power = power * BASE % MOD;
    }
    for (int i = 0; i <= n - m; i++) {
        if (p_hash == t_hash && text.substr(i, m) == pat) result.push_back(i);
        if (i < n - m) t_hash = ((t_hash - text[i] * power) * BASE + text[i + m]) % MOD;
        if (t_hash < 0) t_hash += MOD;
    }
    return result;
}

